const prompts = {
  'STOP':         'Stop. Annule la dernière action et donne un point de situation immédiat.',
  'NAVIGUER':     'Quelles options ai-je disponibles maintenant ? Liste-les brièvement.',
  'SÉLECTIONNER': 'Résume ma situation actuelle en 2 phrases maximum.',
  'VALIDER':      'Confirme et valide ce que nous venons de faire. Donne un retour positif.',
  'SCROLL':       'Propose-moi 3 nouvelles idées ou pistes à explorer sur ce que je fais.',
};
const gesture = $input.first().json.body.gesture;
return [{ json: { prompt: prompts[gesture] ?? 'Aide-moi.', gesture } }];

// Modifie 'model' si tu utilises un autre modèle Ollama
const MODEL = 'llama3.2';
const item  = $input.first().json;

const res = await fetch('http://host.docker.internal:11434/api/chat', {
  method:  'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    model: MODEL,
    messages: [
      { role: 'system', content: 'Tu es Jarvis, un assistant IA local. Réponds en 2 phrases maximum, en français, de façon directe et utile.' },
      { role: 'user',   content: item.prompt }
    ],
    stream: false
  })
});

const data = await res.json();
return [{ json: {
  response: data.message?.content ?? data.response ?? 'Pas de réponse.',
  gesture:  item.gesture,
  model:    MODEL
}}];
